// Text: tokens, weights, pieces of words, and guessing what comes next.
export const tokenize = (s) => s.toLowerCase().match(/[a-z0-9']+/g) || [];
export function stem(w) { // a small suffix stripper in the spirit of Porter's
  if (w.length < 4) return w;
  for (const [suf, rep] of [['ational', 'ate'], ['ization', 'ize'], ['fulness', 'ful'], ['ousness', 'ous'], ['iveness', 'ive'], ['ies', 'y'], ['sses', 'ss'], ['ing', ''], ['edly', ''], ['ed', ''], ['ly', ''], ['es', ''], ['s', '']]) if (w.endsWith(suf) && w.length - suf.length >= 3) { let b = w.slice(0, -suf.length) + rep; if (/(.)\1$/.test(b) && !/(ll|ss|zz)$/.test(b)) b = b.slice(0, -1); return b; }
  return w;
}
export function ngrams(tokens, n) { const out = []; for (let i = 0; i + n <= tokens.length; i++) out.push(tokens.slice(i, i + n).join(' ')); return out; }
export function tf(doc) { const m = new Map(); for (const w of doc) m.set(w, (m.get(w) || 0) + 1); return m; }
export function idf(docs) { const df = new Map(); for (const d of docs) for (const w of new Set(d)) df.set(w, (df.get(w) || 0) + 1); const out = new Map(); for (const [w, c] of df) out.set(w, Math.log(docs.length / c)); return out; }
export function tfidf(docs) { const I = idf(docs); return docs.map((d) => { const t = tf(d), v = new Map(); for (const [w, c] of t) v.set(w, (c / d.length) * I.get(w)); return v; }); }
export function cosineMaps(a, b) { let d = 0, x = 0, y = 0; for (const [w, v] of a) { x += v * v; if (b.has(w)) d += v * b.get(w); } for (const [, v] of b) y += v * v; return x && y ? d / Math.sqrt(x * y) : 0; }
export function bm25(docs, query, k1 = 1.5, b = 0.75) { const N = docs.length, avg = docs.reduce((s, d) => s + d.length, 0) / N, df = new Map(); for (const d of docs) for (const w of new Set(d)) df.set(w, (df.get(w) || 0) + 1); return docs.map((d) => { const t = tf(d); let s = 0; for (const q of query) { const f = t.get(q) || 0, n = df.get(q) || 0; if (!f) continue; s += Math.log(1 + (N - n + 0.5) / (n + 0.5)) * ((f * (k1 + 1)) / (f + k1 * (1 - b + (b * d.length) / avg))); } return s; }); }
export function invertedIndex(docs) { const ix = new Map(); docs.forEach((d, i) => { for (const w of new Set(d)) { if (!ix.has(w)) ix.set(w, []); ix.get(w).push(i); } }); return ix; }
export function soundex(s) { const c = { b: 1, f: 1, p: 1, v: 1, c: 2, g: 2, j: 2, k: 2, q: 2, s: 2, x: 2, z: 2, d: 3, t: 3, l: 4, m: 5, n: 5, r: 6 }; s = s.toLowerCase().replace(/[^a-z]/g, ''); if (!s) return ''; let out = s[0].toUpperCase(), last = c[s[0]] || 0; for (let i = 1; i < s.length && out.length < 4; i++) { const d = c[s[i]] || 0; if (d && d !== last) out += d; if (s[i] !== 'h' && s[i] !== 'w') last = d; } return out.padEnd(4, '0'); }

// ---- byte-pair encoding: merge the commonest adjacent pair, again and again ----
export function bpeInit(words) { return words.map((w) => [...w, '_']); } // '_' marks the end of a word
export function bpePairs(corpus) { const m = new Map(); for (const w of corpus) for (let i = 0; i + 1 < w.length; i++) { const k = w[i] + ' ' + w[i + 1]; m.set(k, (m.get(k) || 0) + 1); } return m; }
export function bpeBest(corpus) { let best = null, bc = 0; for (const [k, c] of bpePairs(corpus)) if (c > bc || (c === bc && best !== null && k < best)) { bc = c; best = k; } return best ? { pair: best.split(' '), count: bc } : null; }
export function bpeMerge(corpus, pair) { return corpus.map((w) => { const out = []; for (let i = 0; i < w.length; i++) { if (i + 1 < w.length && w[i] === pair[0] && w[i + 1] === pair[1]) { out.push(w[i] + w[i + 1]); i++; } else out.push(w[i]); } return out; }); }
export function bpeTrain(words, merges) { let c = bpeInit(words); const rules = []; for (let i = 0; i < merges; i++) { const b = bpeBest(c); if (!b || b.count < 2) break; rules.push(b.pair); c = bpeMerge(c, b.pair); } return { rules, corpus: c }; }
export function bpeEncode(word, rules) { let w = [[...word, '_']]; for (const r of rules) w = bpeMerge(w, r); return w[0]; }

// ---- n-gram language models over characters or tokens ----
export function ngramModel(seq, n, alpha = 0.01) { const ctx = new Map(), vocab = [...new Set(seq)]; for (let i = n - 1; i < seq.length; i++) { const k = seq.slice(i - n + 1, i).join('\u0001'); if (!ctx.has(k)) ctx.set(k, new Map()); const m = ctx.get(k); m.set(seq[i], (m.get(seq[i]) || 0) + 1); } const dist = (prev) => { const k = prev.slice(prev.length - (n - 1)).join('\u0001'), m = ctx.get(k) || new Map(); let t = 0; for (const [, c] of m) t += c; return vocab.map((v) => [v, ((m.get(v) || 0) + alpha) / (t + alpha * vocab.length)]).sort((a, b) => b[1] - a[1]); }; return { vocab, dist, n, contexts: ctx.size }; }
export function perplexity(model, seq) { let ll = 0, c = 0; for (let i = model.n - 1; i < seq.length; i++) { const d = model.dist(seq.slice(0, i)), p = (d.find((x) => x[0] === seq[i]) || [0, 1e-9])[1]; ll += Math.log2(p); c++; } return Math.pow(2, -ll / (c || 1)); }
// softmax with temperature, and the usual ways to cut the tail before sampling
export function softmax(logits, T = 1) { const m = Math.max(...logits), e = logits.map((v) => Math.exp((v - m) / Math.max(T, 1e-6))), s = e.reduce((a, b) => a + b, 0); return e.map((v) => v / s); }
export function reshape(probs, { temperature = 1, topK = 0, topP = 1 } = {}) { let p = temperature === 1 ? probs.slice() : softmax(probs.map((v) => Math.log(Math.max(v, 1e-12))), temperature); const order = p.map((v, i) => [v, i]).sort((a, b) => b[0] - a[0]); let keep = order; if (topK > 0) keep = keep.slice(0, topK); if (topP < 1) { let c = 0; const k2 = []; for (const x of keep) { k2.push(x); c += x[0]; if (c >= topP) break; } keep = k2; } const out = new Array(p.length).fill(0); let s = 0; for (const [v, i] of keep) { out[i] = v; s += v; } return out.map((v) => v / s); }
export function sampleFrom(probs, rng) { let r = rng.u(), i = 0; for (; i < probs.length; i++) { r -= probs[i]; if (r <= 0) return i; } return probs.length - 1; }
// Huffman code lengths
export function huffman(freq) { let nodes = Object.entries(freq).map(([s, f]) => ({ s, f })); if (nodes.length === 1) return { [nodes[0].s]: '0' }; while (nodes.length > 1) { nodes.sort((a, b) => a.f - b.f); const [a, b] = nodes.splice(0, 2); nodes.push({ f: a.f + b.f, l: a, r: b }); } const out = {}; const walk = (n, c) => { if (n.s !== undefined) out[n.s] = c; else { walk(n.l, c + '0'); walk(n.r, c + '1'); } }; walk(nodes[0], ''); return out; }
// word vectors: skip-gram with negative sampling, small enough to watch
export function skipgram(sentences, rng, { dim = 2, window = 2, epochs = 30, lr = 0.05, neg = 3 } = {}) { const vocab = [...new Set(sentences.flat())], ix = new Map(vocab.map((w, i) => [w, i])), V = vocab.length, W = Array.from({ length: V }, () => Array.from({ length: dim }, () => rng.range(-0.5, 0.5))), C = Array.from({ length: V }, () => Array.from({ length: dim }, () => rng.range(-0.5, 0.5))), sg = (z) => 1 / (1 + Math.exp(-z)); const step = (a, b, y) => { const z = W[a].reduce((s, v, d) => s + v * C[b][d], 0), g = (sg(z) - y) * lr; for (let d = 0; d < dim; d++) { const wa = W[a][d]; W[a][d] -= g * C[b][d]; C[b][d] -= g * wa; } }; const epoch = () => { for (const s of sentences) for (let i = 0; i < s.length; i++) for (let j = Math.max(0, i - window); j <= Math.min(s.length - 1, i + window); j++) { if (i === j) continue; step(ix.get(s[i]), ix.get(s[j]), 1); for (let k = 0; k < neg; k++) step(ix.get(s[i]), rng.int(0, V - 1), 0); } }; for (let e = 0; e < epochs; e++) epoch(); return { vocab, W, epoch, vec: (w) => W[ix.get(w)] }; }
